/** 
 * calculate() Will calculate the placements on the map automatically.
 */
static void calculate() {
  Map m_placements = new HashMap();
  try {
    String mapDir = getMapDirectory();
    if (mapDir == null) {
      System.out.println("You need to specify a map name for this to work");
      System.out.println("Shutting down");
      System.exit(0);
    }
    TerritoryData.setMapDir(mapDir);
    Iterator terrIter = TerritoryData.getInstance().getTerritories().iterator();
    System.out.println("Calculating, this may take a while...");
    while (terrIter.hasNext()) {
      String name = (String) terrIter.next();
      Collection points;
      if (TerritoryData.getInstance().hasContainedTerritory(name)) {
        Set containedPolygons = new HashSet();
        Iterator containedIter = TerritoryData.getInstance().getContainedTerritory(name).iterator();
        while (containedIter.hasNext()) {
          String containedName = (String) containedIter.next();
          containedPolygons.addAll(TerritoryData.getInstance().getPolygons(containedName));
        }
        points = getPlacementsStartingAtTopLeft(TerritoryData.getInstance().getPolygons(name), TerritoryData.getInstance().getBoundingRect(name), TerritoryData.getInstance().getCenter(name), containedPolygons);
        m_placements.put(name, points);
      } else {
        points = getPlacementsStartingAtMiddle(TerritoryData.getInstance().getPolygons(name), TerritoryData.getInstance().getBoundingRect(name), TerritoryData.getInstance().getCenter(name));
        m_placements.put(name, points);
      }
      System.out.println(name + ": " + points.size());
    }
    String fileName = JOptionPane.showInputDialog(null, "Save Placements File As");
    if (fileName == null) {
      System.out.println("You chose not to save, Shutting down");
      System.exit(0);
    }
    PointFileReaderWriter.writeOneToMany(new FileOutputStream(fileName), m_placements);
    System.out.println("Data written to :" + new File(fileName).getCanonicalPath());
  } catch (HeadlessException e) {
    System.out.println("Headless environment detected, cannot show dialog");
    System.exit(0);
  } catch (NullPointerException e) {
    System.out.println("Null value encountered, shutting down");
    System.exit(0);
  } catch (Exception ex) {
    ex.printStackTrace();
    System.exit(0);
  }
  System.exit(0);
}
